PROJECT_ROOT <- Sys.getenv('PROJECT_ROOT', unset = '.')

options(stringsAsFactors = FALSE)
suppressPackageStartupMessages({library(ggplot2); library(dplyr); library(tidyr); library(patchwork)})
args <- commandArgs(trailingOnly = TRUE)
root <- if (length(args) >= 1) args[1] else file.path(PROJECT_ROOT, '3-结果与分析', '3-空间转录组', 'Figure5_ctniche8')
data_dir <- if (length(args) >= 2) args[2] else file.path(dirname(dirname(dirname(dirname(root)))), "2-数据")
out <- file.path(root, "25-5C_voom_limma929_cross_disease_consistency")
dir.create(out, recursive = TRUE, showWarnings = FALSE)
read_tsv <- function(x) read.delim(x, check.names = FALSE, quote = "", comment.char = "")
write_tsv <- function(x,n) write.table(x,file.path(out,n),sep="\t",row.names=FALSE,quote=FALSE,na="NA")
save_plot <- function(p,s,w,h) ggsave(file.path(out,paste0(s,".pdf")),p,width=w,height=h,device=cairo_pdf)

ami <- read_tsv(file.path(data_dir,"5A_DE_AMI_IZ.tsv")); icm <- read_tsv(file.path(data_dir,"5A_DE_ICM_FZ.tsv")); hcm <- read_tsv(file.path(data_dir,"5A_DE_HCM.tsv"))
old <- read_tsv(file.path(root,"20-5C_region_corrected_gene_integration","20_03_original929_region_corrected_integrated_evidence.tsv"))
genes929 <- unique(old$gene)
up_raw <- list(`AMI-IZ`=ami$gene[ami$logFC>.1 & ami$FDR<.05],`ICM-FZ`=icm$gene[icm$logFC>.1 & icm$FDR<.05],HCM=hcm$gene[hcm$logFC>.1 & hcm$FDR<.05])
triple944 <- Reduce(intersect,up_raw); removed15 <- setdiff(triple944,genes929)
up <- lapply(up_raw,setdiff,y=removed15)
universe <- Reduce(union,list(ami$gene,icm$gene,hcm$gene))
mem <- tibble(gene=universe,`AMI-IZ`=gene%in%up[["AMI-IZ"]],`ICM-FZ`=gene%in%up[["ICM-FZ"]],HCM=gene%in%up[["HCM"]]) %>%
  mutate(combination=case_when(`AMI-IZ`&`ICM-FZ`&HCM~"AMI-IZ & ICM-FZ & HCM",`AMI-IZ`&`ICM-FZ`~"AMI-IZ & ICM-FZ",`AMI-IZ`&HCM~"AMI-IZ & HCM",`ICM-FZ`&HCM~"ICM-FZ & HCM",`AMI-IZ`~"AMI-IZ only",`ICM-FZ`~"ICM-FZ only",HCM~"HCM only",TRUE~"None"))
write_tsv(mem%>%filter(combination!="None"),"25_01_voom_limma_upregulated_membership.tsv")
write_tsv(tibble(gene=removed15),"25_02_removed15_technical_genes.tsv")

cnt <- mem%>%filter(combination!="None")%>%count(combination,name="n")%>%arrange(desc(n)); cnt$combination<-factor(cnt$combination,levels=cnt$combination)
keys<-as.character(cnt$combination)
mat<-expand_grid(combination=keys,disease=c("AMI-IZ","ICM-FZ","HCM"))%>%mutate(active=case_when(disease=="AMI-IZ"~grepl("AMI-IZ",combination),disease=="ICM-FZ"~grepl("ICM-FZ",combination),TRUE~grepl("HCM",combination)),combination=factor(combination,keys),disease=factor(disease,levels=rev(c("AMI-IZ","ICM-FZ","HCM"))))
setn<-tibble(disease=factor(c("AMI-IZ","ICM-FZ","HCM"),levels=c("AMI-IZ","ICM-FZ","HCM")),n=c(length(up[[1]]),length(up[[2]]),length(up[[3]])))
cc<-c("AMI-IZ only"="#49c2d9","ICM-FZ only"="#f59c76","HCM only"="#fded95","AMI-IZ & ICM-FZ"="#7DB7B2","AMI-IZ & HCM"="#74B6A2","ICM-FZ & HCM"="#D5A96E","AMI-IZ & ICM-FZ & HCM"="#B2182B")
dc<-c("AMI-IZ"="#49c2d9","ICM-FZ"="#f59c76","HCM"="#fded95")
pb<-ggplot(cnt,aes(combination,n,fill=combination))+geom_col(width=.68)+geom_text(aes(label=n),vjust=-.35,fontface="bold",size=3.7)+scale_fill_manual(values=cc,guide="none")+scale_y_continuous(expand=expansion(mult=c(0,.12)))+labs(x=NULL,y="Intersection size",title="Conserved ctniche_8 upregulated genes across disease states",subtitle="Paired sample-by-niche voom-limma pseudobulk; logFC > 0.1 and FDR < 0.05\n15 technical genes removed from the original three-disease intersection")+theme_classic(base_size=12)+theme(axis.text.x=element_blank(),axis.ticks.x=element_blank())
pm<-ggplot(mat,aes(combination,disease))+geom_line(data=mat%>%filter(active)%>%group_by(combination),aes(group=combination),colour="grey35",linewidth=.75)+geom_point(aes(fill=active),shape=21,size=3.7,colour="grey35",stroke=.25)+scale_fill_manual(values=c(`FALSE`="grey88",`TRUE`="grey20"),guide="none")+labs(x=NULL,y=NULL)+theme_minimal(base_size=11)+theme(panel.grid=element_blank(),axis.text.x=element_blank(),axis.ticks=element_blank())
ps<-ggplot(setn,aes(n,disease,fill=disease))+geom_col(width=.58)+geom_text(aes(x=n/2,label=n),fontface="bold",size=3.4)+scale_x_reverse(expand=expansion(mult=c(.04,.2)))+scale_fill_manual(values=dc,guide="none")+labs(x="Set size",y=NULL)+theme_classic(base_size=11)+theme(axis.line.y=element_blank(),axis.ticks.y=element_blank(),axis.text.y=element_blank())
p1<-(plot_spacer()+pb+plot_layout(widths=c(1.45,5)))/(ps+pm+plot_layout(widths=c(1.45,5)))+plot_layout(heights=c(3.4,1.35))
save_plot(p1,"25_Fig1_voom_limma929_upregulated_UpSet",9.4,6.8);write_tsv(cnt,"25_03_intersection_counts.tsv")

evidence<-tibble(comparison=factor(rep(c("edgeR region-corrected replication","LOO robustness"),each=2),levels=c("edgeR region-corrected replication","LOO robustness")),class=c("Replicated in all three: 759","Direction-only: 170","LOO strict: 472","Not LOO strict: 457"),n=c(759,170,472,457))
p2<-ggplot(evidence,aes(comparison,n,fill=class))+geom_col(width=.62)+geom_text(aes(label=n),position=position_stack(vjust=.5),fontface="bold",size=4)+scale_fill_manual(values=c("Replicated in all three: 759"="#4C78A8","Direction-only: 170"="#F2A65A","LOO strict: 472"="#2E8B57","Not LOO strict: 457"="grey78"))+labs(x=NULL,y="Genes within the original 929",fill=NULL,title="Region-corrected support for the original voom-limma 929 genes")+theme_classic(base_size=12)+theme(legend.position="bottom")
save_plot(p2,"25_Fig2_voom_limma929_region_corrected_support",7.8,5.3);write_tsv(evidence,"25_04_region_corrected_support.tsv")

topgenes<-old%>%arrange(conservative_rank)%>%slice_head(n=30)%>%pull(gene)
lfc<-bind_rows(ami%>%filter(gene%in%topgenes)%>%transmute(gene,disease="AMI-IZ",logFC),icm%>%filter(gene%in%topgenes)%>%transmute(gene,disease="ICM-FZ",logFC),hcm%>%filter(gene%in%topgenes)%>%transmute(gene,disease="HCM",logFC))%>%mutate(gene=factor(gene,levels=rev(topgenes)),disease=factor(disease,levels=c("AMI-IZ","ICM-FZ","HCM")))
p3<-ggplot(lfc,aes(disease,gene,fill=logFC))+geom_tile(colour="white",linewidth=.65)+scale_fill_gradient2(low="#2166AC",mid="white",high="#B2182B",midpoint=.8)+labs(x=NULL,y=NULL,fill="logFC",title="Representative genes from the original voom-limma 929 set",subtitle="Top 30 genes ranked by subsequent conservative evidence")+theme_minimal(base_size=11)+theme(panel.grid=element_blank(),axis.text.y=element_text(face="italic"))
save_plot(p3,"25_Fig3_voom_limma929_top30_logFC_heatmap",6.2,8.2);write_tsv(lfc,"25_05_top30_logFC.tsv")
writeLines(c("voom-limma 929 cross-disease consistency","Original three-disease upregulated intersection before technical filtering: 944",paste0("Removed technical genes: ",length(removed15)),paste0("Final strict common set: ",sum(mem$`AMI-IZ`&mem$`ICM-FZ`&mem$HCM)),paste0("Set sizes after removing the same 15 genes: AMI-IZ=",length(up[[1]]),", ICM-FZ=",length(up[[2]]),", HCM=",length(up[[3]]))),file.path(out,"25_06_results_summary.txt"))
message("Completed: ",out)